WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_analysis_enlighten'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '启示分析', 'kp-sl-analysis-enlighten', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：启示分析"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "别人的做法（经验/教训）提炼成普适性的对策！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“A国的发展历程对我国有什么启示？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "启示绝对不是照抄别人的做法！必须“去粗取精、由表及里”。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "材料：“A国给每个买环保车的市民发了 5000 块钱补贴”。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "低分答案：“启示我国要给买环保车的市民发 5000 块钱”。（太具体，没升华）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "高分答案：“启示我国要【完善财政补贴政策，利用经济杠杆引导绿色消费】”。（提炼出了对策的本质）"}]}]}$$ AS jsonb), NULL, '启示分析的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "综合分析", "启示分析"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_analysis_enlighten", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
